def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    components = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] in (1, 8) or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            comp = []
            while stack:
                y, x = stack.pop()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if (0 <= ny < h and 0 <= nx < w
                            and grid[ny][nx] not in (1, 8)
                            and (ny, nx) not in seen):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            components.append(comp)

    for comp in components:
        direction_counts = {}
        for r, c in comp:
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 1:
                    direction = (-dr, -dc)
                    direction_counts[direction] = direction_counts.get(direction, 0) + 1

        if not direction_counts:
            continue
        step_r, step_c = max(direction_counts, key=direction_counts.get)
        axis = 0 if step_r else 1
        step = step_r if step_r else step_c

        layers = {}
        for r, c in comp:
            pos, transverse = (r, c) if axis == 0 else (c, r)
            layers.setdefault(pos, {})[transverse] = grid[r][c]

        ordered = sorted(layers, reverse=(step < 0))
        near, far = ordered[0], ordered[-1]
        first = layers[near]
        second = layers.get(near + step, {})
        period = 2 if any(
            t in second and second[t] != color
            for t, color in first.items()
        ) else 1

        limit = h if axis == 0 else w
        pos = far + step
        while 0 <= pos < limit:
            distance = (pos - near) * step
            template = second if period == 2 and distance % 2 else first
            for transverse, color in first.items():
                value = template.get(transverse, color)
                r, c = (pos, transverse) if axis == 0 else (transverse, pos)
                if out[r][c] != 1:
                    out[r][c] = value
            pos += step

    return out
